# ---------------------------------------------------------------- ОП.09, практическая 3
times = {}
limit = None
for line in open("/root/labs/tools/build/data/outputs/pr3.txt", encoding="utf8").read().splitlines():
    if line.startswith("Предел"):
        limit = int(line.split()[1])
    else:
        times[(limit, line.split()[0])] = float(re.search(r"время ([\d.]+) мс", line).group(1))
t = lambda n: f"{times[(10000, n)]:.2f}".replace(".", ",")
make("op09/pr3", "Практическая работа №3", "Оптимизация программы (ОП.09)", [
    ("h1", "Что сказать в двух словах"),
    ("p", "Модуль ищет все простые числа до заданного предела. Я оптимизировала его по параметру «время выполнения» в три шага и сравнила время. Результат одинаков во всех вариантах, а время при пределе 10000 упало "
          f"с {t('slow')} мс до {t('sieve')} мс."),
    ("h1", "Четыре функции"),
    words([
        ("primes_slow (исходная)", "Для каждого числа n от 2 до limit перебирает все делители d от 2 до n-1. Если n делится на d, помечает число составным. Лишнее: перебор до n-1 и продолжение после найденного делителя."),
        ("primes_sqrt (оптимизация 1)", "Перебирает делители только пока d·d ≤ n (то есть до корня из n) и выходит из цикла на первом делителе (break). Идея: у составного числа есть делитель не больше корня из него."),
        ("primes_odd (оптимизация 2)", "Чётные числа не проверяет (все они, кроме 2, составные): result начинается с [2], range(3, limit + 1, 2) идёт с шагом 2. Делители тоже только нечётные: d += 2."),
        ("primes_sieve (оптимизация 3, решето Эратосфена)", "Создаёт список из True, вычёркивает (False) кратные каждого простого числа, начиная с его квадрата. Деления нет совсем. Это замена алгоритма, то есть глобальная оптимизация."),
    ]),
    ("h1", "Разбор слов и конструкций"),
    words([
        ("range(2, limit + 1)", "Числа от 2 до limit включительно (правая граница в range не входит, поэтому +1)."),
        ("range(3, limit + 1, 2)", "Третье число это шаг: 3, 5, 7, ..."),
        ("n % d == 0", "Остаток от деления n на d равен нулю, то есть n делится на d."),
        ("simple = True / False", "Флаг: пока не найден делитель, число считается простым."),
        ("while d * d <= n:", "Цикл, который работает, пока квадрат делителя не больше n."),
        ("break", "Немедленно выходит из цикла. Здесь после первого найденного делителя дальше искать не нужно."),
        ("result.append(n)", "Добавляет простое число в список результата."),
        ("[True] * (limit + 1)", "Список из limit+1 значений True. is_prime[i] отвечает на вопрос «число i простое?»."),
        ("range(i * i, limit + 1, i)", "Кратные i, начиная с i²: меньшие кратные уже вычеркнуты меньшими простыми."),
        ("int(limit ** 0.5)", "Корень из limit (степень 0,5), приведённый к целому. Дальше корня можно не искать."),
        ("[i for i in range(...) if is_prime[i]]", "Список из тех i, для которых is_prime[i] истинно. Короткая запись цикла с условием."),
        ("time.time()", "Текущее время в секундах. Разность двух замеров это длительность выполнения; умножаем на 1000 для миллисекунд."),
        ("f\"{name:6} ... {spent:.2f}\"", "f-строка: {name:6} выделяет под имя 6 символов, {spent:.2f} выводит число с двумя знаками."),
        ("same = result == reference", "Проверка корректности: список простых чисел должен совпасть с результатом исходной функции."),
    ]),
    ("h1", "Результаты замера (предел 10000)"),
    ("p", f"Исходная: {t('slow')} мс. Оптимизация 1 (до корня): {t('sqrt')} мс. Оптимизация 2 (только нечётные): {t('odd')} мс. Решето: {t('sieve')} мс. Простых чисел до 10000: 1229. Абсолютные значения зависят от компьютера, "
          "важно отношение. Исходный вариант растёт примерно как квадрат предела, оптимизированные заметно медленнее."),
    ("h1", "Вопросы на защите"),
    *qa([
        ("Что такое оптимизация?", "Преобразование программы, которое не меняет её смысл, но уменьшает время выполнения или размер."),
        ("Виды оптимизации по охвату?", "Глобальная (вся программа), локальная (несколько соседних операторов), квазилокальная (фрагменты фиксированной структуры, например циклы)."),
        ("Способы оптимизации?", "Вынесение вычислений из повторяющихся участков, упрощение действий, вычисление констант заранее, удаление ненужных конструкций, сокращение размера, экономия памяти."),
        ("Почему оптимизация, а не минимизация?", "Минимальная программа получается слишком сложной для понимания и сопровождения, а затраты на неё выше выигрыша."),
        ("Почему особое внимание циклам?", "Тело цикла выполняется много раз, выигрыш от одной операции умножается на число повторений."),
        ("К чему может привести оптимизация?", "Код становится сложнее, легче внести ошибку, труднее сопровождать. Поэтому результат каждого варианта сверяют с исходным."),
        ("Какие ограничения у решета?", "Оно быстрее, но использует память под список размером с предел."),
        ("Почему достаточно делителей до корня?", "Если n = p·q и p больше корня, то q меньше корня. Значит у составного числа всегда есть делитель не больше корня из n."),
    ]),
])

